import { Page } from "@playwright/test";
import { BasePage } from "./BasePage";

// Generated by Tracewright from the Phase 1 page-object registry; every locator below
// was verified against the live app. Regenerate instead of editing by hand.
export class CheckoutPage extends BasePage {
  readonly url_pattern = "http://localhost:4000/checkout";

  constructor(page: Page) {
    super(page);
  }

  get logoutButton() {
    return this.page.getByRole("button", { name: "Log out" });
  }

  get checkoutHeading() {
    return this.page.getByRole("heading", { name: "Checkout" });
  }

  get placeOrderButton() {
    return this.page.getByRole("button", { name: "Place order" });
  }

  get orderTotal() {
    return this.page.getByTestId("order-total");
  }

  // Exists only after: "open http://localhost:4000/cart; fill Discount code with SAVE20; click Apply discount code; open http://localhost:4000/checkout"
  get discountSummary() {
    return this.page.getByTestId("discount-summary");
  }
}
